calls = {"count": 0}


@retry(3)
def fetch() -> str:
    calls["count"] += 1
    if calls["count"] == 1:
        raise ConnectionError("réseau")
    return "ok"


try:
    print(f"Résultat: {fetch()} | nom conservé: {fetch.__name__}")
except ConnectionError as error:
    print(f"Erreur non gérée: {error}")

with transaction():
    pass

try:
    with transaction():
        raise ValueError("boom")
except ValueError:
    pass
